SELECT 'users-joined-2026', 'The 2026 Cohort', 'code', 'Easy', 'Fintech',
       'Filtering', ARRAY['where','date']::text[], 'Growth reviews this year''s signups. Return `name` and `joined_at` of users who joined in 2026, earliest first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT name, joined_at FROM users WHERE joined_at >= ''2026-01-01'' ORDER BY joined_at;',
       '["A simple date lower bound","Earliest first = ascending order"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 88
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'users-joined-2026');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'name-search-islam', 'Directory Search', 'code', 'Easy', 'Fintech',
       'String Functions', ARRAY['like']::text[], 'Support''s directory search: return `user_id` and `name` of users whose name contains **"Islam"**, by user_id.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT user_id, name FROM users WHERE name LIKE ''%Islam%'' ORDER BY user_id;',
       '["LIKE with % wildcards on both sides","Case matters with LIKE; the data capitalises Islam"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 84
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'name-search-islam');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'reversed-transactions-log', 'Reversal Audit Log', 'code', 'Easy', 'Fintech',
       'Joins', ARRAY['join','where']::text[], 'Every reversal is audited. Return `txn_id`, user `name`, `amount`, and `txn_at` of reversed transactions, newest first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT t.txn_id, u.name, t.amount, t.txn_at
FROM transactions t JOIN users u ON u.user_id = t.user_id
WHERE t.status = ''reversed'' ORDER BY t.txn_at DESC;',
       '["Join for the name, filter status = ''reversed''","Newest first = ORDER BY txn_at DESC"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 80
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'reversed-transactions-log');

