SELECT 'district-user-counts', 'Users per District', 'code', 'Easy', 'Fintech',
       'Aggregation', ARRAY['group-by','count']::text[], 'Return each `district` and its user count (`users_count`), largest first, ties alphabetical.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT district, COUNT(*) AS users_count FROM users GROUP BY district ORDER BY users_count DESC, district;',
       '["GROUP BY district","Two-level ORDER BY for stable ties"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 86
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'district-user-counts');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'weekend-transactions', 'Weekend Transaction Volume', 'code', 'Medium', 'Fintech',
       'Date Functions', ARRAY['extract','dow']::text[], 'Do weekends behave differently? Return total successful volume (`weekend_volume`) for transactions on Saturdays and Sundays — one row. (June 6/7, 13/14... 2026 are weekend dates in the data.)',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT SUM(amount) AS weekend_volume
FROM transactions
WHERE status = ''success'' AND EXTRACT(DOW FROM txn_at) IN (0, 6);',
       '["EXTRACT(DOW FROM ts): 0 = Sunday, 6 = Saturday","One aggregate row — no GROUP BY"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 55
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'weekend-transactions');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'fee-free-users', 'Users Who Never Paid a Fee', 'code', 'Medium', 'Fintech',
       'Aggregation', ARRAY['having','sum']::text[], 'Pricing wonders who rides free. Return `user_id` and `name` of users whose successful transactions carried **zero total fees**, by user_id.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT u.user_id, u.name
FROM users u JOIN transactions t ON t.user_id = u.user_id
WHERE t.status = ''success''
GROUP BY u.user_id, u.name
HAVING SUM(t.fee) = 0
ORDER BY u.user_id;',
       '["SUM(fee) per user","HAVING SUM(fee) = 0 — the test is on an aggregate"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 58
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'fee-free-users');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'agent-vs-app-mix', 'Agent vs App Split', 'code', 'Medium', 'Fintech',
       'Conditional Aggregation', ARRAY['case-when','null']::text[], 'One row for the channel report: count of successful **agent-assisted** transactions (`agent_txns`) and **app-only** transactions (`app_txns`).',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT
  COUNT(*) FILTER (WHERE agent_id IS NOT NULL) AS agent_txns,
  COUNT(*) FILTER (WHERE agent_id IS NULL) AS app_txns
FROM transactions WHERE status = ''success'';',
       '["agent_id NULL-ness is the channel","COUNT(*) FILTER (WHERE ...) or SUM(CASE...)"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 60
