SELECT 'above-average-fees', 'Above-Average Fee Payers', 'code', 'Medium', 'Fintech',
       'Subqueries', ARRAY['scalar-subquery','having']::text[], 'Return `user_id` and total fees paid (`fees_paid`) of users who paid **more total fees than the average user''s total**, highest first.',
