SELECT 'early-payoff-candidates', 'Case: Early Payoff Candidates', 'case_study', 'Hard', 'Fintech',
       'Subqueries', ARRAY['cte','ratio']::text[], '**Scenario.** Marketing wants to offer early-payoff discounts to *active* borrowers who have already repaid **at least 30%** of principal — they finish loans, and they come back.

Return `borrower`, `principal`, `repaid`, and `pct_done` (1 decimal), most complete first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_microloan'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_microloan'), ''), 'WITH repaid AS (
