)
SELECT l.borrower, l.principal, rp.total AS repaid,
       ROUND(100.0 * rp.total / l.principal, 1) AS pct_done
FROM loans l JOIN repaid rp ON rp.loan_id = l.loan_id
WHERE l.status = ''active'' AND rp.total >= 0.3 * l.principal
ORDER BY pct_done DESC;',
       '["Repayments per loan in a CTE","The 30% test compares two columns — plain WHERE works after the join","Active loans only"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, 1800, 33
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'early-payoff-candidates');

