SELECT 'vip-cutoff-analysis', 'Case: Drawing the VIP Line', 'case_study', 'Hard', 'E-Commerce',
       'Window Functions', ARRAY['cume','rank']::text[], '**Scenario.** Loyalty wants a VIP tier for customers who drive the top of revenue. Rank ordering customers by delivered revenue and show the running cumulative share.

Return `name`, `revenue`, `rank`, and `cumulative_pct` (running share of total delivered revenue, 1 decimal), best first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), 'WITH per_customer AS (
  SELECT c.name, SUM(oi.quantity * oi.unit_price) AS revenue
  FROM customers c
  JOIN orders o ON o.customer_id = c.customer_id
  JOIN order_items oi ON oi.order_id = o.order_id
  WHERE o.status = ''delivered''
  GROUP BY c.name
)
SELECT name, revenue,
       RANK() OVER (ORDER BY revenue DESC) AS rank,
       ROUND(100.0 * SUM(revenue) OVER (ORDER BY revenue DESC) / SUM(revenue) OVER (), 1) AS cumulative_pct
FROM per_customer ORDER BY revenue DESC;',
       '["Revenue per customer in a CTE","Running total: SUM(...) OVER (ORDER BY revenue DESC)","Divide by the grand total window"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, 1800, 28
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'vip-cutoff-analysis');

