SELECT 'hub-cod-exposure', 'COD Exposure per Hub', 'code', 'Hard', 'Logistics',
       'Joins', ARRAY['multi-join','exposure']::text[], 'Which hub carries the cash risk? Sum COD of parcels whose **latest attempt** is not delivered, per the attempting rider''s hub. Return hub `city` and `exposure`.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'logistics_courier'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'logistics_courier'), ''), 'WITH latest AS (
  SELECT d.*, ROW_NUMBER() OVER (PARTITION BY parcel_id ORDER BY picked_at DESC) AS rn
  FROM deliveries d
)
SELECT h.city, SUM(p.cod_amount) AS exposure
FROM latest l
JOIN parcels p ON p.parcel_id = l.parcel_id
JOIN riders r ON r.rider_id = l.rider_id
JOIN hubs h ON h.hub_id = r.hub_id
WHERE l.rn = 1 AND l.status <> ''delivered'' AND p.cod_amount > 0
GROUP BY h.city ORDER BY exposure DESC;',
       '["Latest attempt via ROW_NUMBER ... ORDER BY picked_at DESC","Join up to hubs through riders","Only COD parcels count"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, 1800, 27
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'hub-cod-exposure');

