SELECT 'consecutive-usage-growth', 'Two Days of Growth in a Row', 'code', 'Hard', 'Telco',
       'Window Functions', ARRAY['lag','trend']::text[], 'Find subscriber-days where data usage grew versus the **previous day** for that subscriber. Return `name`, `usage_date`, `data_mb`, and `prev_mb`, largest jump first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'telco_network'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'telco_network'), ''), 'SELECT name, usage_date, data_mb, prev_mb FROM (
  SELECT s.name, u.usage_date, u.data_mb,
         LAG(u.data_mb) OVER (PARTITION BY u.sub_id ORDER BY u.usage_date) AS prev_mb
  FROM subscribers s JOIN usage_daily u ON u.sub_id = s.sub_id
) t WHERE prev_mb IS NOT NULL AND data_mb > prev_mb
ORDER BY data_mb - prev_mb DESC;',
       '["LAG per subscriber ordered by date","Growth = current > previous","First day per subscriber has NULL prev"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, 1800, 36
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'consecutive-usage-growth');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'plan-upgrade-shortlist', 'The Upgrade Shortlist', 'code', 'Hard', 'Telco',
       'Subqueries', ARRAY['cte','comparison']::text[], 'Sales wants subscribers whose average daily data, projected to 30 days, **exceeds their plan''s allowance**. Return `name`, plan `allowance_gb`, and `projected_gb` (30 × daily average ÷ 1024, 1 decimal), biggest overshoot first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'telco_network'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'telco_network'), ''), 'WITH daily AS (
  SELECT sub_id, AVG(data_mb) AS avg_mb FROM usage_daily GROUP BY sub_id
)
SELECT s.name, p.data_gb AS allowance_gb,
       ROUND(30 * d.avg_mb / 1024.0, 1) AS projected_gb
FROM subscribers s
JOIN plans p ON p.plan_id = s.plan_id
JOIN daily d ON d.sub_id = s.sub_id
WHERE 30 * d.avg_mb / 1024.0 > p.data_gb
ORDER BY 30 * d.avg_mb / 1024.0 - p.data_gb DESC;',
       '["Daily average per subscriber in a CTE","Project: 30 × avg ÷ 1024 GB","Compare against the plan allowance in WHERE"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, 1800, 30
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'plan-upgrade-shortlist');

