       '', '', '',
       '[]'::jsonb, '[{"label":"A","text":"Yes — the whole table is one implicit group, and HAVING filters that group"},{"label":"B","text":"No — HAVING always requires GROUP BY"},{"label":"C","text":"Only in MySQL, not Postgres"},{"label":"D","text":"Yes, but it behaves exactly like WHERE"}]'::jsonb, 'A',
       NULL, 0, NULL, 43
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'mcq-having-without-groupby');

