SELECT 'recharge-behavior-segments', 'Case: Recharge Behaviour Segments', 'case_study', 'Medium', 'Telco',
       'Conditional Aggregation', ARRAY['bucketing','segments']::text[], '**Scenario.** CVM segments the base by top-up style: `''big_ticket''` (average recharge ≥ ৳300), `''regular''` (৳150–299), `''micro''` (< ৳150).

Per recharging subscriber: `name`, `avg_recharge` (2 decimals), and `segment`, largest average first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'telco_network'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'telco_network'), ''), 'SELECT s.name, ROUND(AVG(r.amount), 2) AS avg_recharge,
       CASE WHEN AVG(r.amount) >= 300 THEN ''big_ticket''
            WHEN AVG(r.amount) >= 150 THEN ''regular''
            ELSE ''micro'' END AS segment
FROM subscribers s JOIN recharges r ON r.sub_id = s.sub_id
GROUP BY s.name ORDER BY avg_recharge DESC;',
       '["Segment on the AVG aggregate with CASE","The CASE can reference AVG(...) directly in SELECT"]'::jsonb, '[]'::jsonb, NULL,
       NULL, 0, NULL, 52
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'recharge-behavior-segments');

