SELECT 'launch-2-payer-profile', 'Step 2: Who Pays?', 'code', 'Medium', 'Fintech',
       'Joins', ARRAY['join','group-by']::text[], 'Profile the payers by geography: per `district`, distinct paying users (`payers`) and payment volume (`volume`), by volume descending.',
