SELECT 'launch-3-repeat-payers', 'Step 3: The Habit Signal', 'code', 'Medium', 'Fintech',
       'Aggregation', ARRAY['having']::text[], 'A habit means spending from the wallet, not just topping it up. Return `user_id` and spend count (`spend_count`) of users with **2 or more** successful spend transactions (payments or send-money combined).',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT user_id, COUNT(*) AS spend_count
