INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
   parent_id, order_index, time_limit_secs, success_rate)
SELECT 'launch-4-wallet-share', 'Step 4: Share of Wallet', 'code', 'Hard', 'Fintech',
       'Conditional Aggregation', ARRAY['case-when','ratio']::text[], 'The honest answer: for each user who made any successful payment, what share of their total successful spend (payments + send_money) went to payments? Return `user_id`, `payment_total`, `spend_total`, and `payment_share_pct` (1 decimal), highest share first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'fintech_wallet'), ''), 'SELECT user_id,
       SUM(CASE WHEN txn_type = ''payment'' THEN amount ELSE 0 END) AS payment_total,
       SUM(amount) AS spend_total,
       ROUND(100.0 * SUM(CASE WHEN txn_type = ''payment'' THEN amount ELSE 0 END) / SUM(amount), 1) AS payment_share_pct
FROM transactions
WHERE status = ''success'' AND txn_type IN (''payment'',''send_money'')
GROUP BY user_id
HAVING SUM(CASE WHEN txn_type = ''payment'' THEN amount ELSE 0 END) > 0
ORDER BY payment_share_pct DESC;',
       '["Restrict the universe to payment + send_money in WHERE","Payment share via conditional SUM over the full SUM","HAVING keeps actual payers"]'::jsonb, '[]'::jsonb, NULL,
       (SELECT id FROM public.careerprep_questions WHERE slug = 'mission-launch-day'), 3, 1800, 32
WHERE NOT EXISTS (SELECT 1 FROM public.careerprep_questions WHERE slug = 'launch-4-wallet-share');

INSERT INTO public.careerprep_questions
  (slug, title, question_type, difficulty, industry, category, tags, content_md,
   schema_sql, initial_sql, solution_sql, hints, options, correct_option,
