SELECT 'stockout-1-velocity', 'Step 1: Sales Velocity', 'code', 'Easy', 'E-Commerce',
       'Aggregation', ARRAY['group-by','sum']::text[], 'Which products move? Return `name` and total units across **all non-cancelled** orders (`units_moved`), fastest first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), 'SELECT p.name, SUM(oi.quantity) AS units_moved
FROM products p
JOIN order_items oi ON oi.product_id = p.product_id
JOIN orders o ON o.order_id = oi.order_id
WHERE o.status <> ''cancelled''
GROUP BY p.name ORDER BY units_moved DESC;',
       '["Exclude cancelled with <>","SUM(quantity) per product"]'::jsonb, '[]'::jsonb, NULL,
       (SELECT id FROM public.careerprep_questions WHERE slug = 'mission-stockout-scare'), 0, NULL, 79
