SELECT 'stockout-2-hero-buyers', 'Step 2: Who Buys the Hero Product?', 'code', 'Medium', 'E-Commerce',
       'Joins', ARRAY['multi-join','where']::text[], 'Zoom into the **Power Bank 20000mAh**: return each buying customer''s `name`, `city`, order `status`, and `quantity`, by quantity descending.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), 'SELECT c.name, c.city, o.status, oi.quantity
FROM customers c
JOIN orders o ON o.customer_id = c.customer_id
