       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), 'SELECT c.city, SUM(oi.quantity) AS units
