SELECT 'stockout-4-substitutes', 'Step 4: The Substitute Pitch', 'code', 'Hard', 'E-Commerce',
       'Subqueries', ARRAY['not-in','same-category']::text[], 'If the Power Bank stocks out, what do we push instead? Return other **Electronics** products with their delivered-order units (`units_sold`, 0 if never sold), best sellers first — excluding the Power Bank itself.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'ecommerce_shop'), ''), 'SELECT p.name,
