LEFT JOIN orders o ON o.order_id = oi.order_id
WHERE p.category = ''Electronics'' AND p.name <> ''Power Bank 20000mAh''
GROUP BY p.name ORDER BY units_sold DESC;',
       '["LEFT JOINs keep never-sold substitutes","FILTER (or CASE) restricts the SUM to delivered","Exclude the hero product in WHERE"]'::jsonb, '[]'::jsonb, NULL,
