SELECT 'peak-4-fragile-lanes', 'Step 4: The Fragile Lanes', 'code', 'Hard', 'Logistics',
       'Joins', ARRAY['failure-rate','group-by']::text[], 'Finale: lanes that already show cracks. Per receiver_area with any attempts, return `receiver_area`, `attempts`, `non_delivered` (failed or still in transit), and `risk_pct` (1 decimal), riskiest first.',
       COALESCE((SELECT schema_sql FROM _worlds WHERE name = 'logistics_courier'), ''), COALESCE((SELECT initial_sql FROM _worlds WHERE name = 'logistics_courier'), ''), 'SELECT p.receiver_area, COUNT(*) AS attempts,
       COUNT(*) FILTER (WHERE d.status <> ''delivered'') AS non_delivered,
       ROUND(100.0 * COUNT(*) FILTER (WHERE d.status <> ''delivered'') / COUNT(*), 1) AS risk_pct
FROM parcels p JOIN deliveries d ON d.parcel_id = p.parcel_id
